import{_ as t,c as a,o,al as n}from"./chunks/framework.B3j7FRen.js";const u=JSON.parse('{"title":"BlackLab Corpus Query Language (BCQL)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/corpus-query-language.md","filePath":"guide/040_corpus-query-language.md","lastUpdated":1748439130000}'),r={name:"guide/corpus-query-language.md"};function s(i,e,c,d,l,p){return o(),a("div",null,e[0]||(e[0]=[n(`<h1 id="blacklab-corpus-query-language-bcql" tabindex="-1">BlackLab Corpus Query Language (BCQL) <a class="header-anchor" href="#blacklab-corpus-query-language-bcql" aria-label="Permalink to &quot;BlackLab Corpus Query Language (BCQL)&quot;">​</a></h1> <p>BlackLab Corpus Query Language or BCQL is a powerful query language for text corpora.</p> <p>It is a dialect of the <a href="http://cwb.sourceforge.net/files/CQP_Tutorial/" title="http://cwb.sourceforge.net/files/CQP_Tutorial/" target="_blank" rel="noreferrer">CQP Query Language</a> introduced by the IMS Corpus WorkBench (CWB). Several other corpus engines support a similar language, such as the <a href="https://www.sketchengine.co.uk/documentation/corpus-querying/" title="https://www.sketchengine.co.uk/documentation/corpus-querying/" target="_blank" rel="noreferrer">Lexicom Sketch Engine</a>. The various dialects are very similar, but differ in some of the more advanced features.</p> <p>This page will introduce BCQL and show the features that BlackLab supports.</p> <p>BlackLab started out as purely a token-based corpus engine. The next section shows BCQL&#39;s token-based features. After that, we will look at (syntactic) relations querying. Finally, we compare BCQL to CQP, so users familiar with that dialect can avoid common pitfalls.</p> <h2 id="token-based-querying" tabindex="-1">Token-based querying <a class="header-anchor" href="#token-based-querying" aria-label="Permalink to &quot;Token-based querying&quot;">​</a></h2> <h3 id="matching-a-token" tabindex="-1">Matching a token <a class="header-anchor" href="#matching-a-token" aria-label="Permalink to &quot;Matching a token&quot;">​</a></h3> <p>With BCQL you can specify a pattern of tokens (i.e. words) you&#39;re looking for.</p> <p>A simple such pattern is:</p> <pre><code>[word=&#39;man&#39;]
</code></pre> <p>This simply searches for all occurrences of the word <em>man</em>.</p> <p>Each corpus has a default annotation; usually <em>word</em>. Using this fact, this query can be written even simpler:</p> <pre><code>&#39;man&#39;
</code></pre> <p>Note that double and single quotes are interchangeable in BCQL (which is not true for all dialects). In this document we will use single quotes.</p> <h4 id="multiple-annotations" tabindex="-1">Multiple annotations <a class="header-anchor" href="#multiple-annotations" aria-label="Permalink to &quot;Multiple annotations&quot;">​</a></h4> <p>If your corpus includes the per-word annotations <em>lemma</em> (i.e. headword) and <em>pos</em> (part-of-speech, i.e. noun, verb, etc.), you can query those as well.</p> <p>For example:</p> <pre><code>[lemma=&#39;search&#39; &amp; pos=&#39;noun&#39;]
</code></pre> <p>This query would match <em>search</em> and <em>searches</em> where used as a noun. (your data may use different part-of-speech tags, of course)</p> <h4 id="negation" tabindex="-1">Negation <a class="header-anchor" href="#negation" aria-label="Permalink to &quot;Negation&quot;">​</a></h4> <p>You can use the &quot;does not equal&quot; operator (!=) to search for all words except nouns:</p> <pre><code>[pos != &#39;noun&#39;]
</code></pre> <h4 id="regular-expressions" tabindex="-1">Regular expressions <a class="header-anchor" href="#regular-expressions" aria-label="Permalink to &quot;Regular expressions&quot;">​</a></h4> <p>The strings between quotes can also contain &quot;wildcards&quot;, of sorts. To be precise, they are <a href="http://en.wikipedia.org/wiki/Regular_expression" target="_blank" rel="noreferrer">regular expressions</a>, which provide a flexible way of matching strings of text. For example, to find <em>man</em> or <em>woman</em> (in the default annotation <em>word</em>), use:</p> <pre><code>&#39;(wo)?man&#39;
</code></pre> <p>And to find lemmas starting with <em>under</em>, use:</p> <pre><code>[lemma=&#39;under.*&#39;]
</code></pre> <p>Explaining regular expression syntax is beyond the scope of this document, but for a complete overview, see <a href="http://www.regular-expressions.info/" target="_blank" rel="noreferrer">regular-expressions.info</a> for a general overview, or <a href="https://www.elastic.co/guide/en/elasticsearch/reference/current/regexp-syntax.html" target="_blank" rel="noreferrer">Lucene&#39;s regular expression syntax</a> specifically, which has a few quirks.</p> <details class="details custom-block"><summary>Escaping and literal strings</summary> <p>To find characters with special meaning in a regular expression, such as the period, you need to escape them with a backslash:</p> <pre><code>[lemma=&#39;etc\\.&#39;]
</code></pre> <p>Alternatively, you can use a &quot;literal string&quot; by prefixing the string with an <code>l</code>:</p> <pre><code>[lemma=l&#39;etc.&#39;]
</code></pre> <p>Note that some unexpected characters may be considered special regex characters, such as <code>&lt;</code> and <code>&gt;</code>. See the above link to Lucene&#39;s regex documentation for more details.</p></details> <h4 id="matching-any-token" tabindex="-1">Matching any token <a class="header-anchor" href="#matching-any-token" aria-label="Permalink to &quot;Matching any token&quot;">​</a></h4> <p>Sometimes you want to match any token, regardless of its value.</p> <p>Of course, this is usually only useful in a larger query, as we will explore next. But we&#39;ll introduce the syntax here.</p> <p>To match any token, use the match-all pattern, which is just a pair of empty square brackets:</p> <pre><code>[]
</code></pre> <h3 id="a-sequence-of-tokens" tabindex="-1">A sequence of tokens <a class="header-anchor" href="#a-sequence-of-tokens" aria-label="Permalink to &quot;A sequence of tokens&quot;">​</a></h3> <p>You can search for sequences of words as well (i.e. phrase searches, but with many more possibilities). To search for the phrase <em>the tall man</em>, use this query:</p> <pre><code>&#39;the&#39; &#39;tall&#39; &#39;man&#39;
</code></pre> <p>It might seem a bit clunky to separately quote each word, but this allows us the flexibility to specify exactly what kinds of words we&#39;re looking for.</p> <p>For example, if you want to know all single adjectives used with man (not just <em>tall</em>), use this:</p> <pre><code>&#39;an?|the&#39; [pos=&#39;ADJ&#39;] &#39;man&#39;
</code></pre> <p>This would also match <em>a wise man</em>, <em>an important man</em>, <em>the foolish man</em>, etc.</p> <p>If we don&#39;t care about the part of speech between the article and <em>man</em>, we can use the match-all pattern we showed before:</p> <pre><code>&#39;an?|the&#39; [] &#39;man&#39;
</code></pre> <p>This way we might match something like <em>the cable man</em> as well as <em>a wise man</em>.</p> <h3 id="regular-expression-operators-on-tokens" tabindex="-1">Regular expression operators on tokens <a class="header-anchor" href="#regular-expression-operators-on-tokens" aria-label="Permalink to &quot;Regular expression operators on tokens&quot;">​</a></h3> <p>Really powerful token-based queries become possible when you use the regular expression operators on whole tokens as well. If we want to see not just single adjectives applied to <em>man</em>, but multiple as well:</p> <pre><code>[pos=&#39;ADJ&#39;]+ &#39;man&#39;
</code></pre> <p>This query matches <em>little green man</em>, for example. The plus sign after <code>[pos=&#39;ADJ&#39;]</code> says that the preceding part should occur one or more times (similarly, <code>*</code> means &quot;zero or more times&quot;, and <code>?</code> means &quot;zero or once&quot;).</p> <p>If you only want matches with exactly two or three adjectives, you can specify that too:</p> <pre><code>[pos=&#39;ADJ&#39;]{2,3} &#39;man&#39;
</code></pre> <p>Or, for two or more adjectives:</p> <pre><code>[pos=&#39;ADJ&#39;]{2,} &#39;man&#39;
</code></pre> <p>You can group sequences of tokens with parentheses and apply operators to the whole group as well. To search for a sequence of nouns, each optionally preceded by an article:</p> <pre><code>(&#39;an?|the&#39;? [pos=&#39;NOU&#39;])+
</code></pre> <p>This would, for example, match the well-known palindrome <em>a man, a plan, a canal: Panama!</em> (provided the punctuation marks were not indexed as separate tokens)</p> <h3 id="case-and-diacritics-sensitivity" tabindex="-1">Case- and diacritics sensitivity <a class="header-anchor" href="#case-and-diacritics-sensitivity" aria-label="Permalink to &quot;Case- and diacritics sensitivity&quot;">​</a></h3> <p>BlackLab defaults to (case and diacritics) <em>insensitive</em> search. That is, it ignores differences in upper- and lowercase, as well as diacritical marks (accented characters). So searching for <code>&#39;panama&#39;</code> will also find <em>Panama</em>.</p> <p>To match a pattern sensitively, prefix it with <code>(?-i)</code>:</p> <pre><code>&#39;(?-i)Panama&#39;
</code></pre> <details class="details custom-block"><summary>compare to other corpus engines</summary> <p>CWB and Sketch Engine both default to <em>sensitive</em> search.</p></details> <h3 id="matching-xml-elements" tabindex="-1">Matching XML elements <a class="header-anchor" href="#matching-xml-elements" aria-label="Permalink to &quot;Matching XML elements&quot;">​</a></h3> <p>Your input data may contains &quot;spans&quot;: marked regions of text, such as paragraphs, sentences, named entities, etc. If your input data is XML these may be XML elements, but they may also be marked in other ways. Non-XML formats may also define spans.</p> <p>Finding text in relation to these spans is done using an XML-like syntax, regardless of the exact input data format.</p> <h4 id="finding-spans" tabindex="-1">Finding spans <a class="header-anchor" href="#finding-spans" aria-label="Permalink to &quot;Finding spans&quot;">​</a></h4> <p>If you want to find all the sentence spans in your data:</p> <pre><code>&lt;s/&gt;
</code></pre> <p>Note that forward slash before the closing bracket. This way of referring to the span means &quot;the whole span&quot;. Compare this to <code>&lt;s&gt;</code>, which means &quot;the start of the span&quot;, and <code>&lt;/s&gt;</code>, which means &quot;the end of the span&quot;.</p> <p>So to find only the starts of sentences, use:</p> <pre><code>&lt;s&gt;
</code></pre> <p>This would find zero-length hits at the position before the first word. Similarly, <code>&lt;/s&gt;</code> finds the ends of sentences. Not very useful, but we can combine these with other queries.</p> <h4 id="words-at-the-start-or-end-of-a-span" tabindex="-1">Words at the start or end of a span <a class="header-anchor" href="#words-at-the-start-or-end-of-a-span" aria-label="Permalink to &quot;Words at the start or end of a span&quot;">​</a></h4> <p>More useful might be to find the first word of each sentence:</p> <pre><code>&lt;s&gt; []
</code></pre> <p>or sentences ending in <em>that</em>:</p> <pre><code>&#39;that&#39; &lt;/s&gt;
</code></pre> <p>(Note that this assumes the period at the end of the sentence is not indexed as a separate token - if it is, you would use <code>&#39;that&#39; &#39;.&#39; &lt;/s&gt;</code> instead)</p> <h4 id="words-inside-a-span" tabindex="-1">Words inside a span <a class="header-anchor" href="#words-inside-a-span" aria-label="Permalink to &quot;Words inside a span&quot;">​</a></h4> <p>You can also search for words occurring inside a specific span. Say you&#39;ve run named entity recognition on your data, so all names of people are tagged with the <code>person</code> span. To find the word <em>baker</em> as part of a person&#39;s name, use:</p> <pre><code>&#39;baker&#39; within &lt;person/&gt;
</code></pre> <p>The above query will just match the word <em>baker</em> as part of a person&#39;s name. But you&#39;re likely more interested in the entire name that contains the word <em>baker</em>. So, to find those full names, use:</p> <pre><code>&lt;person/&gt; containing &#39;baker&#39;
</code></pre> <div class="tip custom-block"><p class="custom-block-title">Using a regular expression for the span name</p> <p>You can match multiple span types (e.g. both <code>&lt;person/&gt;</code> and <code>&lt;location/&gt;</code>) using a regular expression:</p> <pre><code>&#39;baker&#39; within &lt;&#39;person|location&#39; /&gt;
</code></pre> <p>To match all spans in the corpus, use:</p> <pre><code>&lt;&#39;.+&#39; /&gt;
</code></pre></div> <div class="tip custom-block"><p class="custom-block-title">Capturing all surrounding spans</p> <p>If you want to know all spans that surround (or actually overlap with) each of your hits, use::</p> <pre><code>with-spans(&#39;baker&#39;)
</code></pre> <p>or</p> <pre><code>with-spans(&#39;baker&#39;, &lt;&#39;person|location&#39; /&gt;, &#39;props&#39;)
</code></pre> <p>The second example will capture a list of matching spans in the match info named <code>props</code>.</p> <p>Only the first parameter for <code>with-spans</code> is required. The second parameter defaults to <code>&lt;&#39;.+&#39;/&gt;</code> (all tags); the third defaults to <code>&#39;with-spans&#39;</code>.</p></div> <h4 id="other-uses-for-within-and-containing" tabindex="-1">Other uses for within and containing <a class="header-anchor" href="#other-uses-for-within-and-containing" aria-label="Permalink to &quot;Other uses for within and containing&quot;">​</a></h4> <p>As you might have guessed, you can use <code>within</code> and <code>containing</code> with any other query as well. For example:</p> <pre><code>([pos=&#39;ADJ&#39;]+ containing &#39;tall&#39;) &#39;man&#39;
</code></pre> <p>will find adjectives applied to man, where one of those adjectives is <em>tall</em>.</p> <h3 id="labeling-tokens-capturing-groups" tabindex="-1">Labeling tokens, capturing groups <a class="header-anchor" href="#labeling-tokens-capturing-groups" aria-label="Permalink to &quot;Labeling tokens, capturing groups&quot;">​</a></h3> <p>Just like in regular expressions, it is possible to &quot;capture&quot; part of the match for your query as a named group. Everything you capture is returned with the hit in a response section called <em>match info</em>.</p> <p>Example:</p> <pre><code>&#39;an?|the&#39; A:[pos=&#39;ADJ&#39;] &#39;man&#39;
</code></pre> <p>The adjective part of the match will be captured in a group named <em>A</em>.</p> <p>You can capture multiple words as well:</p> <pre><code>&#39;an?|the&#39; adjectives:[pos=&#39;ADJ&#39;]+ &#39;man&#39;
</code></pre> <p>This will capture the adjectives found for each match in a captured group named <em>adjectives</em>.</p> <p>The capture name can also just be a number:</p> <pre><code>&#39;an?|the&#39; 1:[pos=&#39;ADJ&#39;]+ &#39;man&#39;
</code></pre> <details class="details custom-block"><summary>Compared to other corpus engines</summary> <p>CWB and Sketch Engine offer similar functionality, but instead of capturing part of the match, they label a single token.</p> <p>BlackLab can capture a span of tokens of any length, capture relations and spans with all their details, and even capture lists of relations, such as all relations in a sentence (relations are described later in this document).</p></details> <div class="tip custom-block"><p class="custom-block-title">Spans are captured automatically</p> <p>If your query involves spans like <code>&lt;s/&gt;</code>, it will automatically be captured under the span name (<code>s</code> in this case). You can override the capture name by specifying it in the query, e.g. <code>A:&lt;s/&gt;</code>.</p></div> <h3 id="capture-constraints" tabindex="-1">Capture constraints <a class="header-anchor" href="#capture-constraints" aria-label="Permalink to &quot;Capture constraints&quot;">​</a></h3> <p>If you tag certain tokens with labels, you can also apply &quot;capture constraints&quot; (also known as &quot;global constraints&quot;)
on these tokens. This is a way of relating different tokens to one another, for example requiring that they correspond
to the same word:</p> <pre><code>A:[] &#39;by&#39; B:[] :: A.word = B.word
</code></pre> <p>This would match <em>day by day</em>, <em>step by step</em>, etc.</p> <details class="details custom-block"><summary>Multiple-value annotations and constraints</summary> <p>Unfortunately, capture constraints can only access the first value indexed for an annotation. If you need this kind of
functionality in combination with multi-values constraints, you&#39;ll have to find a way around this limitation.</p> <p>Some queries can be rewritten so they don&#39;t need a capture constraint. For example,
<code>A:[word=&quot;some&quot;] B:[word=&quot;queries&quot;] :: A.lemma=&quot;some&quot; &amp; B.lemma=&quot;query&quot;</code> can also be written as
<code>A:[word=&quot;some&quot; &amp; lemma=&quot;some&quot;] B:[word=&quot;queries&quot; &amp; lemma=&quot;query&quot;]</code>, which does work with multiple annotation values.
But this is rare.</p> <p>In other cases, you might be able to add extra annotations or use spans (&quot;inline tags&quot;) to get around this limitation.</p></details> <h4 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h4> <p>You can also use a few special functions in capture constraints. For example, ensure that words occur in the right order:</p> <pre><code>(&lt;s&gt; containing A:&#39;cat&#39;) containing B:&#39;fluffy&#39; :: start(B) &lt; start(A)
</code></pre> <p>Here we find sentences containing both <em>cat</em> and <em>fluffy</em> (in some order), but then require that <em>fluffy</em> occurs before <em>cat</em>.</p> <p>Of course this particular query would be better expressed as <code>&lt;s/&gt; containing &#39;fluffy&#39; []* &#39;cat&#39;</code>. As a general rule,
capture constraints can be a bit slower, so only use them when you need to.</p> <h4 id="local-capture-constraints" tabindex="-1">Local capture constraints <a class="header-anchor" href="#local-capture-constraints" aria-label="Permalink to &quot;Local capture constraints&quot;">​</a></h4> <p>Unlike most other corpus engines, BlackLab allows you to place capture constraints inside a parenthesized expression.
Be careful that the constraint only refers to labels that are captured inside the parentheses, though!</p> <p>This is valid and would match <em>over and over again</em>:</p> <pre><code>(A:[] &#39;and&#39; B:[] :: A.word = B.word) &#39;again&#39;
</code></pre> <p>This is NOT valid (may not produce an error, but the results are undefined):</p> <pre><code>A:[] (&#39;and&#39; B:[] :: A.word = B.word) &#39;again&#39;   # BAD
</code></pre> <h3 id="lookahead-lookbehind" tabindex="-1">Lookahead/lookbehind <a class="header-anchor" href="#lookahead-lookbehind" aria-label="Permalink to &quot;Lookahead/lookbehind&quot;">​</a></h3> <div class="tip custom-block"><p class="custom-block-title">Supported from v4.0</p> <p>This feature will be supported from BlackLab 4.0 (and current development snapshots).</p></div> <p>Just like most regular expressions engines, BlackLab supports lookahead and lookbehind assertions. These match a position in the text but do not consume any tokens. They are useful for matching a token only if it is followed or preceded by other token(s).</p> <p>For example, to find the word <em>cat</em> only if it is followed by <em>in the hat</em>:</p> <pre><code>&#39;cat&#39; (?= &#39;in&#39; &#39;the&#39; &#39;hat&#39;)
</code></pre> <p>Similarly, to find the word <em>dog</em>, but only if it is preceded by <em>very good</em>:</p> <pre><code>(?&lt;= &#39;very&#39; &#39;good&#39;) &#39;dog&#39;
</code></pre> <p>Negative lookahead is also supported. To only find <em>cat</em> if it is not followed by <em>call</em>:</p> <pre><code>&#39;cat&#39; (?! &#39;call&#39;)
</code></pre> <p>And negative lookbehind:</p> <pre><code>(?&lt;! &#39;bad&#39;) &#39;dog&#39;
</code></pre> <h3 id="finding-punctuation-pseudo-annotations" tabindex="-1">Finding punctuation / pseudo-annotations <a class="header-anchor" href="#finding-punctuation-pseudo-annotations" aria-label="Permalink to &quot;Finding punctuation / pseudo-annotations&quot;">​</a></h3> <p>(The following applies to corpora that index punctuation as the <code>punct</code> property of the next word, not to corpora that index punctuation as a separate token)</p> <p>Often in BlackLab, the punctuation and spaces between words will be indexed as a property named <code>punct</code>. This property always contains the spaces and interpunction that occurs before the word where it is indexed.</p> <p>Because of where it is indexed, it can be tricky to find specific punctuation <em>after</em> a certain word. To find the word <code>dog</code> followed by a comma, you&#39;d need to do something like this:</p> <pre><code>&#39;dog&#39; [punct=&#39;, *&#39;]
</code></pre> <p>Because spaces are also indexed with the <code>punct</code> annotation, you need to include them in the regex as well.</p> <p>BlackLab supports <em>pseudo-annotations</em> that can help with this. You can pretend that every corpus has a <code>punctBefore</code> and <code>punctAfter</code> annotation. So you can write the above query as:</p> <pre><code>[word=&#39;dog&#39; &amp; punctAfter=&#39;,&#39;]
</code></pre> <p>Note that in special cases where more than one punctuation mark is indexed with a word, you may still need to tweak your regular expression. For example, if your input data contained the fragment &quot;(white) dog, (black) cat&quot;, the above query would not work because the <code>punct</code> annotation for the word after <code>dog</code> would have the value <code>, (</code>. You&#39;d have to use a more general regular expression:</p> <pre><code>[word=&#39;dog&#39; &amp; punctAfter=&#39;,.*&#39;]
</code></pre> <p>Note that <code>punctBefore</code> and <code>punctAfter</code> look like annotations when used in the query, but are not; they will not be in the results and you cannot group on them. You can group on the <code>punct</code> annotation they are based on, because that is actually a part of the index.</p> <h2 id="relations-querying" tabindex="-1">Relations querying <a class="header-anchor" href="#relations-querying" aria-label="Permalink to &quot;Relations querying&quot;">​</a></h2> <div class="tip custom-block"><p class="custom-block-title">Supported from v4.0</p> <p>Indexing and searching relations will be supported from BlackLab 4.0 (and current development snapshots).</p></div> <p>Relations show how (groups of) words are related to one another. One of the most common types of relations is the dependency relation, which shows grammatical dependency between words.</p> <p>If your corpus contains relations, you can query those as well. One advantage of this style of querying is that it&#39;s much easier to find nonadjacent words related to one another, or two related words regardless of what order they occur in.</p> <details class="details custom-block"><summary>How to index relations</summary> <p>Indexing relations is explained <a href="./how-to-configure-indexing.html#indexing-dependency-relations">here</a>.</p></details> <p>Querying relations is essentially done by building a partial tree of relations constraints. BlackLab will try and find this structure in the corpus. Relations queries can be combined with &quot;regular&quot; token-level queries as well.</p> <div class="tip custom-block"><p class="custom-block-title">Treebank systems</p> <p>BlackLab supports limited relations querying, but is not as powerful as a full
treebank system, which is primarily designed for this style of search. Links to some treebank systems can be found <a href="https://github.com/instituutnederlandsetaal/BlackLab/blob/dev/doc/technical/design/design-relations-queries.md#research-into-treebank-systems" target="_blank" rel="noreferrer">here</a>. For BlackLab&#39;s relations querying limitations, see <a href="#limitation-descendant-search">below</a>.</p></div> <h3 id="an-example-dependency-tree" tabindex="-1">An example dependency tree <a class="header-anchor" href="#an-example-dependency-tree" aria-label="Permalink to &quot;An example dependency tree&quot;">​</a></h3> <p>Let&#39;s use an example to illustrate the various querying options. Here&#39;s a simple dependency tree for the phrase <em>I have a fluffy cat</em>:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>      |</span></span>
<span class="line"><span>     have</span></span>
<span class="line"><span>    /    \\</span></span>
<span class="line"><span> (subj)   (obj)</span></span>
<span class="line"><span> /          \\</span></span>
<span class="line"><span>I            cat</span></span>
<span class="line"><span>           /   |</span></span>
<span class="line"><span>        (det)(amod)</span></span>
<span class="line"><span>        /      |</span></span>
<span class="line"><span>       a     fluffy</span></span></code></pre></div><h3 id="finding-specific-relation-types" tabindex="-1">Finding specific relation types <a class="header-anchor" href="#finding-specific-relation-types" aria-label="Permalink to &quot;Finding specific relation types&quot;">​</a></h3> <p>We might want to find object relations in our data. We can do this as follows:</p> <pre><code>_ -obj-&gt; _
</code></pre> <p>This will find <em>have a fluffy cat</em> (the span of text covering the two ends of the relation), with a match info group named for the relation type (<em>obj</em>) containing the relation details between <em>have</em> and <em>cat</em>.</p> <p>The two <code>_</code> marks in the query simply means we only care about the relation type, not the source or target of the relation. If we specifically want to find instances where <em>cat</em> is the object of the sentence, we can use this instead:</p> <pre><code>_ -obj-&gt; &#39;cat&#39;
</code></pre> <p>So you can see that the token-based queries described previously are still useful here.</p> <details class="details custom-block"><summary>Can I use [] instead of _ ?</summary> <p>As explained above, <code>_</code> in a relation expression means &quot;any source or target&quot;. You might be tempted to use <code>[]</code> instead, especially if you know your relations always have a single-token source and target. This works just fine, but it&#39;s a bit slower (it has to double-check that source and target are actually of length 1), so we recommend sticking with <code>_</code>.</p> <p>(the actual equivalent of <code>_</code> here is <code>[]*</code> (zero or more tokens with no restrictions), but that makes for less readable queries)</p></details> <h3 id="a-note-on-terminology" tabindex="-1">A note on terminology <a class="header-anchor" href="#a-note-on-terminology" aria-label="Permalink to &quot;A note on terminology&quot;">​</a></h3> <p>For dependency relations, linguists call the left side the <em>head</em> of the relation and the right side the <em>dependent</em>. However, because dependency relations aren&#39;t the only class of relation, and because the term <em>head</em> can be a bit confusing (there&#39;s also the &quot;head of an arrow&quot;, but that&#39;s the other end!), we will use <em>source</em> and <em>target</em>.</p> <p>When talking about tree structures, we will also use <em>parent</em> and <em>child</em>.</p> <table tabindex="0"><thead><tr><th>Context</th> <th>Terms</th></tr></thead> <tbody><tr><td>Dependency relations</td> <td><code>head --&gt; dependent</code></td></tr> <tr><td>Relations in BlackLab</td> <td><code>source --&gt; target</code></td></tr> <tr><td>Searching tree structures</td> <td><code>parent --&gt; child</code></td></tr></tbody></table> <h3 id="finding-relation-types-using-regular-expressions" tabindex="-1">Finding relation types using regular expressions <a class="header-anchor" href="#finding-relation-types-using-regular-expressions" aria-label="Permalink to &quot;Finding relation types using regular expressions&quot;">​</a></h3> <p>We can specify the relation type as a regular expression as well. To find both subject and object relations, we could use:</p> <pre><code>_ -subj|obj-&gt; _
</code></pre> <p>or:</p> <pre><code>_ -.*bj-&gt; _
</code></pre> <p>If you find it clearer, you can use parentheses around the regular expression:</p> <pre><code>_ -(subj|obj)-&gt; _
</code></pre> <p>With our example tree, the above queries will find all subject relations and all object relations. Each hit will have one relation in the match info. To find multiple relations per hit, read on.</p> <details class="details custom-block"><summary>Relation classes</summary> <p>When indexing relations in BlackLab, you assign them a <em>class</em>, a short string indicating what family of relations it belongs to. For example, you could assign the class string <code>dep</code> to dependency relations. An <code>obj</code> relation would become <code>dep::obj</code>.</p> <p>To simplify things, <code>rel</code> is the default relation class in BlackLab. If you index relations without a class, they will automatically get this class. Similarly, when searching, if you don&#39;t specify a class, <code>rel::</code> will be prepended to the relation type. So if you&#39;re not indexing different classes of relations, you can just ignore the classes.</p></details> <h3 id="root-relations" tabindex="-1">Root relations <a class="header-anchor" href="#root-relations" aria-label="Permalink to &quot;Root relations&quot;">​</a></h3> <p>A dependency tree has a single root relation. A root relation is special relation that only has a target and no source. Its relation type is usually just called <em>root</em>. In our example, the root points to the word <em>have</em>.</p> <p>You can find root relations with a special unary operator:</p> <pre><code>^--&gt; _
</code></pre> <p>This will find all root relations. The details for the root relation will be returned in the match info.</p> <p>Of course you can place constraints on the target of the root relation as well:</p> <pre><code>^--&gt; &#39;have&#39;
</code></pre> <p>This will only find root relations pointing to the word <em>have</em>.</p> <h3 id="finding-two-relations-with-the-same-source" tabindex="-1">Finding two relations with the same source <a class="header-anchor" href="#finding-two-relations-with-the-same-source" aria-label="Permalink to &quot;Finding two relations with the same source&quot;">​</a></h3> <p>What if we want to find the subject and object relations of a sentence, both linked to the same source (the verb in the sentence)? We can do that using a semicolon to separate the two <em>target constraints</em> (or <em>child constraints</em>):</p> <pre><code>_ -subj-&gt; _ ;
  -obj-&gt; _
</code></pre> <p>As you can see, the source or parent is specified only once at the beginning. Then you may specify one or more target constraints (a relation type plus target, e.g. <code>-subj-&gt; _</code>), separated by semicolons.</p> <p>The above query will find hits covering the words involved in both relations, with details for the two relations in the match info of each hit. In our example, it would find the entire sentence <em>I have a fluffy cat</em>.</p> <details class="details custom-block"><summary>Target constraint uniqueness</summary> <p>Note that when matching multiple relations with the same source this way, BlackLab will enforce that they are unique. That is, two target constraints will only match two different relations.</p></details> <h3 id="negative-child-constraints" tabindex="-1">Negative child constraints <a class="header-anchor" href="#negative-child-constraints" aria-label="Permalink to &quot;Negative child constraints&quot;">​</a></h3> <p>You may want to have negative constraints, such as making sure that <em>dog</em> is not the object of the sentence. This can be done by prefixing the relation operator with <code>!</code>:</p> <pre><code>_  -subj-&gt; _ ;
  !-obj-&gt; &#39;dog&#39;
</code></pre> <p>Note that this is different from :</p> <pre><code>_  -subj-&gt; _ ;
   -obj-&gt; [word != &#39;dog&#39;]
</code></pre> <p>The second query requires an object relation where the target is a word other than <em>dog</em>; that is, the object relation must exist. By contrast, in the first case, we only require that there exists no object relation with the target <em>dog</em>, so this might match sentences without an object as well as sentences with an object that is not <em>dog</em>.</p> <h3 id="searching-over-multiple-levels-in-the-tree" tabindex="-1">Searching over multiple levels in the tree <a class="header-anchor" href="#searching-over-multiple-levels-in-the-tree" aria-label="Permalink to &quot;Searching over multiple levels in the tree&quot;">​</a></h3> <p>What if we want to query over multiple levels of the tree? For example, we want to find sentences where the target of the <code>subj</code> relation is the source of an <code>amod</code> relation pointing to <em>fluffy</em>, such as in our example tree.</p> <pre><code>_ -subj-&gt; _ -amod-&gt; &#39;fluffy&#39;
</code></pre> <p>We can combine the techniques as well, for example if we also want to find the object of the sentence like before:</p> <pre><code>_ -subj-&gt; (_ -amod-&gt; _) ;
  -obj-&gt; _
</code></pre> <p>As you can see, the value of the expression <code>(_ -amod-&gt; _)</code> is actually the <em>source</em> of the <code>amod</code> relation, so we can easily use it as the target of the <code>subj</code> relation.</p> <p>The <code>-..-&gt;</code> operator is right-associative (as you can see from the first example), but we do need parentheses here, or the parent of the <code>-obj-&gt;</code> relation would be ambiguous.</p> <h3 id="limitation-descendant-search" tabindex="-1">Limitation: descendant search <a class="header-anchor" href="#limitation-descendant-search" aria-label="Permalink to &quot;Limitation: descendant search&quot;">​</a></h3> <p>One current limitation compared to dedicated treebank systems is the lack
of support for finding descendants that are not direct children.</p> <p>For example, if we want to look for sentences with the verb <em>have</em> and the word <em>fluffy</em> somewhere as an adjectival modifier in that sentence, we can&#39;t query something like this:</p> <pre><code>^--&gt; &#39;have&#39; --&gt;&gt; -amod-&gt; &#39;fluffy&#39;   # DOES NOT WORK
</code></pre> <p>Instead, we have to know how many nodes are between <em>have</em> and <em>fluffy</em>, e.g. this does work:</p> <pre><code>^--&gt; &#39;have&#39; --&gt; _ -amod-&gt; &#39;fluffy&#39;
</code></pre> <p>Supporting arbitrary descendant search with decent performance is a challenge that we may try to tackle in the future.</p> <p>For now, you might be able to work around this limitation using a hybrid between token-based and relations querying, e.g.:</p> <pre><code>(&lt;s/&gt; containing (^--&gt; &#39;have&#39;)) containing (_ -amod-&gt; &#39;fluffy&#39;)
</code></pre> <h3 id="advanced-relations-querying-features" tabindex="-1">Advanced relations querying features <a class="header-anchor" href="#advanced-relations-querying-features" aria-label="Permalink to &quot;Advanced relations querying features&quot;">​</a></h3> <p>Most users won&#39;t need this, but they might come in handy in some cases.</p> <h4 id="controlling-the-resulting-span" tabindex="-1">Controlling the resulting span <a class="header-anchor" href="#controlling-the-resulting-span" aria-label="Permalink to &quot;Controlling the resulting span&quot;">​</a></h4> <p>As shown in the previous section, relation expressions return the source of the matching relation by default. But what if you want a different part of the relation?</p> <p>For example, if we want to find targets of the <em>amod</em> relation, we can do this:</p> <pre><code>rspan(_ -amod-&gt; _, &#39;target&#39;)
</code></pre> <p>If we want the entire span covering both the source and the target (and anything in between):</p> <pre><code>rspan(_ -amod-&gt; _, &#39;full&#39;)
</code></pre> <p>Note that <em>full</em> is the default value for the second parameter, so this will work too:</p> <pre><code>rspan(_ -amod-&gt; _)
</code></pre> <p><code>rspan</code> supports another option: <em>all</em> will return a span covering all of the relations matched by your query.</p> <pre><code>rspan(_ -subj-&gt; (_ -amod-&gt; _) ; -obj-&gt; _, &#39;all&#39;)
</code></pre> <p>Because this is pretty useful when searching relations, there&#39;s an easy way to apply this <code>rspan</code> operation: just add a parameter <code>adjusthits=yes</code> to your BlackLab Server URL. Note that if your query already starts with a call to <code>rspan</code>, <code>adjusthits=yes</code> won&#39;t do anything.</p> <h4 id="capturing-all-relations-in-a-sentence" tabindex="-1">Capturing all relations in a sentence <a class="header-anchor" href="#capturing-all-relations-in-a-sentence" aria-label="Permalink to &quot;Capturing all relations in a sentence&quot;">​</a></h4> <p>If you want to capture all relations in the sentence containing your match, use:</p> <pre><code>&#39;elephant&#39; within rcapture(&lt;s/&gt;)
</code></pre> <p>What actually happens here is that all relations in the matched clause are returned in the match info.</p> <p>You can pass a second parameter with the match info name for the list of captured relations (defaults to <em>captured_rels</em>):</p> <pre><code>&#39;elephant&#39; within rcapture(&lt;s/&gt;, &#39;relations&#39;)
</code></pre> <p>If you only want to capture certain relations, you specify a third parameter that is a regular expression filter on the relation type. For example, to only capture relations in the <code>fam</code> class, use:</p> <pre><code>&#39;elephant&#39; within rcapture(&lt;s/&gt;, &#39;relations&#39;, &#39;fam::.*&#39;)
</code></pre> <h4 id="cross-field-relations" tabindex="-1">Cross-field relations <a class="header-anchor" href="#cross-field-relations" aria-label="Permalink to &quot;Cross-field relations&quot;">​</a></h4> <p>It is possible to have a corpus with multiple annotated fields, with relations that point from a position or span in one field to another. Annotated fields should be named e.g. <code>contents__original</code> and <code>contents__corrected</code> for this to work, and a relation from the first to the second field could be found like this:</p> <pre><code>&#39;mistpyed&#39; --&gt;corrected &#39;mistyped&#39;
</code></pre> <p>As you can see, the target version is appended to the relation operator. The source version is determined by the main annotated field searched (the <code>field</code> parameter for BlackLab Server; will default to the main annotated field, which is the first one you defined in your indexing configuration).</p> <p>Cross-field relations are used to enable parallel corpora, which we&#39;ll discuss next.</p> <h2 id="parallel-corpus-querying" tabindex="-1">Parallel corpus querying <a class="header-anchor" href="#parallel-corpus-querying" aria-label="Permalink to &quot;Parallel corpus querying&quot;">​</a></h2> <div class="tip custom-block"><p class="custom-block-title">Supported from v4.0</p> <p>Indexing and searching parallel corpoora will be supported from BlackLab 4.0 (and current development snapshots).</p></div> <p>A parallel corpus is a corpus that contains multiple versions of the corpus content, usually from different languages and/or time periods, and record the alignment between the versions at different levels (e.g. paragraph, sentence, word).</p> <p>For example, you could have a parallel corpus of EU Parliament discussions in the various European languages, or a parallel corpus of different translations of a classic work such as Homer&#39;s Odyssey.</p> <details class="details custom-block"><summary>How to index a parallel corpus</summary> <p>Indexing parallel corpora is explained <a href="./how-to-configure-indexing.html#indexing-parallel-corpora">here</a>.</p></details> <p>BlackLab&#39;s parallel corpus functionality uses cross-field relations to find alignments between the content versions available in your corpus.</p> <p>The alignments operator <code>==&gt;</code> is specifically to find alignments between versions in your corpus. It essentially means &quot;capture all relations between (part of) the left and right span&quot;. It will capture a list of relations in the response.</p> <h3 id="basic-parallel-querying" tabindex="-1">Basic parallel querying <a class="header-anchor" href="#basic-parallel-querying" aria-label="Permalink to &quot;Basic parallel querying&quot;">​</a></h3> <p>For example, if your corpus contains fields <code>contents__en</code> (English version) and <code>contents__nl</code> (Dutch version), and English is the default field (the first one defined in your indexing config), you can find the Dutch translation of an English word using:</p> <pre><code>&#39;cat&#39; ==&gt;nl _
</code></pre> <p>The hit for this query will be <code>cat</code> in the English field, and the match info will contain a group named <code>rels</code> with all alignment relations found (just the one in this case, between the word <code>cat</code> and its Dutch equivalent). The hit response structure will also contain an <code>otherFields</code> section containing the corresponding Dutch content fragment. The location of the Dutch word aligned with the English word <code>cat</code> can be found from the relation in the <code>rel</code> capture, which includes <code>targetField</code>, <code>targetStart</code> and <code>targetEnd</code>.</p> <p>Assuming your data has both sentence and word alignments, and you want to find all alignments for a sentence containing <code>cat</code>, you could use:</p> <pre><code>&lt;s/&gt; containing &#39;cat&#39; ==&gt;nl _
</code></pre> <p>This should find aligning English and Dutch sentences, including any word alignments between words in those sentences. You can also filter by alignment type, as we&#39;ll show later.</p> <details class="details custom-block"><summary>Required versus optional alignment</summary> <p>The <code>==&gt;</code> operator will <em>require</em> that an alignment exists. If you wish to see all hits on the left side of the <code>==&gt;nl</code> regardless of whether any alignments to the right side can be found, use <code>==&gt;nl?</code>.</p> <p>For example, if you&#39;re searching for translations of <code>cat</code> to Dutch, with <code>==&gt;nl</code> you will <em>only</em> see instances where <code>cat</code> is aligned to a Dutch word; on the other hand, with <code>==&gt;nl?</code> you will see both English <code>cat</code> hits where the translation to Dutch was found, and <code>cat</code> hits where it wasn&#39;t.</p></details> <h3 id="switching-the-main-search-field" tabindex="-1">Switching the main search field <a class="header-anchor" href="#switching-the-main-search-field" aria-label="Permalink to &quot;Switching the main search field&quot;">​</a></h3> <p>If you want to search the Dutch version instead, and find alignments with the English version, you would use this query:</p> <pre><code>&#39;kat&#39; ==&gt;en _
</code></pre> <p>But of course, the main search field shouldn&#39;t be <code>contents__en</code> in this case; we want to switch it to <code>contents__nl</code>. You can specify a main search field other than the default with the BLS parameter <code>field</code>. In this case, if you specify <code>field=nl</code>. BlackLab will automatically recognize that you&#39;re specifying a version of the main annotated field and use the correct &#39;real&#39; field, probably <code>contents__nl</code> in this case.</p> <h3 id="filtering-the-target-span" tabindex="-1">Filtering the target span <a class="header-anchor" href="#filtering-the-target-span" aria-label="Permalink to &quot;Filtering the target span&quot;">​</a></h3> <p>In the previous example, we used <code>_</code> as the target span. This is the default, and means &quot;the best matching span&quot;.</p> <p>But you can also specify a different target span. For example, to find where <em>fluffy</em> was translated to <em>pluizig</em>:</p> <pre><code>&#39;fluffy&#39; ==&gt;nl &#39;pluizig&#39;
</code></pre> <p>This will execute the left and right queries on their respective fields and match the hits by their alignment relations.</p> <h3 id="multiple-alignment-queries" tabindex="-1">Multiple alignment queries <a class="header-anchor" href="#multiple-alignment-queries" aria-label="Permalink to &quot;Multiple alignment queries&quot;">​</a></h3> <p>You can also use multiple alignment operators in a single query to match to more than one other version:</p> <pre><code>&#39;fluffy&#39; ==&gt;nl &#39;pluizig&#39; ;
         ==&gt;de &#39;flauschig&#39;
</code></pre> <h3 id="only-matching-some-alignment-relations" tabindex="-1">Only matching some (alignment) relations <a class="header-anchor" href="#only-matching-some-alignment-relations" aria-label="Permalink to &quot;Only matching some (alignment) relations&quot;">​</a></h3> <p>Just like with other relations queries, you can filter by type:</p> <pre><code>&#39;fluffy&#39; =word=&gt;nl &#39;pluizig&#39;
</code></pre> <p>This will only find relations of type <code>word</code>. The type filter will automatically determine the capture name as well, so any relation(s) found will be captured as <code>word</code> in this case instead of <code>rels</code> (unless an explicit name is assigned, see below).</p> <h3 id="renaming-the-relations-capture" tabindex="-1">Renaming the relations capture <a class="header-anchor" href="#renaming-the-relations-capture" aria-label="Permalink to &quot;Renaming the relations capture&quot;">​</a></h3> <p>You can use a override the default name <code>rels</code> for the alignment operator&#39;s captures:</p> <pre><code>&lt;s/&gt; alignments:==&gt;nl _
</code></pre> <p>Now the alignment relations will be captured in a group named <code>alignments</code>.</p> <h3 id="capturing-in-target-fields" tabindex="-1">Capturing in target fields <a class="header-anchor" href="#capturing-in-target-fields" aria-label="Permalink to &quot;Capturing in target fields&quot;">​</a></h3> <p>You can capture parts of the target query like normal, e.g.:</p> <pre><code>&quot;and&quot; w1:[] ==&gt;nl &quot;en&quot; w2:[]
</code></pre> <p>There will be one match info named <code>w1</code> for the primary field searched (English in this case), and one named <code>w2</code> for the target field (Dutch).</p> <h3 id="rfield-get-only-hits-from-a-target-field" tabindex="-1">rfield(): get only hits from a target field <a class="header-anchor" href="#rfield-get-only-hits-from-a-target-field" aria-label="Permalink to &quot;rfield(): get only hits from a target field&quot;">​</a></h3> <p>If you only want to see hits from the target field, you can use the <code>rfield</code> operator:</p> <pre><code>rfield(&#39;fluffy&#39; =word=&gt;nl &#39;pluizig&#39;, &#39;nl&#39;)
</code></pre> <p>This can be useful when, after running a parallel query, you want to show the highlighted contents of one of the target fields. In this case, you would like to only get the target hits (in <code>contents__nl</code>), not the source hits (in e.g. <code>contents__en</code>).</p> <h2 id="advanced-subjects" tabindex="-1">Advanced subjects <a class="header-anchor" href="#advanced-subjects" aria-label="Permalink to &quot;Advanced subjects&quot;">​</a></h2> <h3 id="operator-precedence" tabindex="-1">Operator precedence <a class="header-anchor" href="#operator-precedence" aria-label="Permalink to &quot;Operator precedence&quot;">​</a></h3> <p>This is the precedence of the different CQL operators in BlackLab, from highest to lowest. The highest precedence operators &quot;bind most tightly&quot;. See the examples below.</p> <p>Inside token brackets <code>[ ]</code>:</p> <table tabindex="0"><thead><tr><th>Operator</th> <th>Description</th> <th>Associativity</th></tr></thead> <tbody><tr><td><code>!</code></td> <td>logical not</td> <td>right-to-left</td></tr> <tr><td><code>=</code> <code>!=</code></td> <td>(not) equals</td> <td>left-to-right</td></tr> <tr><td><code>&amp;</code> <code>|</code></td> <td>logical and/or</td> <td>left-to-right</td></tr></tbody></table> <p>At the sequence level (i.e. outside token brackets):</p> <table tabindex="0"><thead><tr><th>Operator</th> <th>Description</th> <th>Associativity</th></tr></thead> <tbody><tr><td><code>!</code></td> <td>logical not</td> <td>right-to-left</td></tr> <tr><td><code>[ ]</code></td> <td>token brackets</td> <td>left-to-right</td></tr> <tr><td><code>( )</code></td> <td>function call</td> <td>left-to-right</td></tr> <tr><td><code>*</code> <code>+</code> <code>?</code><br><code>{n}</code> <code>{n,m}</code></td> <td>repetition</td> <td>left-to-right</td></tr> <tr><td><code>:</code></td> <td>capture</td> <td>right-to-left</td></tr> <tr><td><code>&lt; /&gt;</code> <code>&lt; &gt;</code> <code>&lt;/ &gt;</code></td> <td>span (start/end)</td> <td>left-to-right</td></tr> <tr><td><code>[] []</code></td> <td>sequence<br>(implied operator)</td> <td>left-to-right</td></tr> <tr><td><code>|</code> <code>&amp;</code></td> <td>union/intersection</td> <td>left-to-right</td></tr> <tr><td><code>--&gt; [ ; --&gt; ]</code><br><code>^--&gt;</code><br><code>==&gt; [ ; ==&gt; ]</code></td> <td>child relations<br>root relation<br>alignment</td> <td>right-to-left</td></tr> <tr><td><code>within</code> <code>containing</code></td> <td>position filter</td> <td>right-to-left</td></tr> <tr><td><code>::</code></td> <td>capture constraint</td> <td>left-to-right</td></tr></tbody></table> <p>NOTES:</p> <ul><li>you can always use grouping parens <code>( )</code> (at either token or sequence level) to override this precedence.</li> <li>notice that <code>|</code> and <code>&amp;</code> have the <em>same</em> precedence; don&#39;t rely on <code>&amp;</code> binding more tightly than <code>|</code> or vice versa, which you might be used to from other languages.</li></ul> <p>A few examples:</p> <table tabindex="0"><thead><tr><th>Query</th> <th>Interpreted as</th></tr></thead> <tbody><tr><td><code>[word = &#39;can&#39; &amp; pos != &#39;verb&#39;]</code></td> <td><code>[ (word = &#39;can&#39;) &amp; (pos != &#39;verb&#39;) ]</code></td></tr> <tr><td><code>[pos = &#39;verb&#39; | pos = &#39;noun&#39; &amp; word = &#39;can&#39;]</code></td> <td><code>[ (pos = &#39;verb&#39; | pos = &#39;noun&#39;) &amp; word = &#39;can&#39;]</code></td></tr> <tr><td><code>A:&#39;very&#39;+</code></td> <td><code>A:(&#39;very&#39;+)</code></td></tr> <tr><td><code>A:_ --&gt; B:_</code></td> <td><code>(A:_) --&gt; (B:_)</code></td></tr> <tr><td><code>_ -obj-&gt; _ -amod-&gt; _</code></td> <td><code>_ -obj-&gt; (_ -amod-&gt; _)</code></td></tr> <tr><td><code>!&#39;d.*&#39; &amp; &#39;.e.*&#39;</code></td> <td><code>(!&#39;d.*&#39;) &amp; &#39;.e.*&#39;</code>, meaning <br><code>[word != &#39;d.*&#39; &amp; word = &#39;.e.*&#39;]</code></td></tr> <tr><td><code>&#39;cow&#39; within &lt;pasture/&gt; containing &#39;grass&#39;</code></td> <td><code>&#39;cow&#39; within (&lt;pasture/&gt; containing &#39;grass&#39;)</code></td></tr></tbody></table> <h3 id="supported-features-differences-from-cwb" tabindex="-1">Supported features, differences from CWB <a class="header-anchor" href="#supported-features-differences-from-cwb" aria-label="Permalink to &quot;Supported features, differences from CWB&quot;">​</a></h3> <p>For those who already know CQL, here&#39;s a quick overview of the extent of BlackLab&#39;s support for this query language. If you a feature we don&#39;t support yet is important to you, please let us know. If it&#39;s quick to add, we may be able to help you out.</p> <h3 id="supported-features" tabindex="-1">Supported features <a class="header-anchor" href="#supported-features" aria-label="Permalink to &quot;Supported features&quot;">​</a></h3> <p>BlackLab currently supports (arguably) most of the important features of Corpus Query Language:</p> <ul><li>Matching on token annotations, using regular expressions and <code>=</code>, <code>!=</code>, <code>!</code>. Example: <code>[word=&#39;bank&#39;]</code> (or just <code>&#39;bank&#39;</code>)</li> <li>Case/accent sensitive matching. Note that, unlike in CWB, case-INsensitive matching is currently the default. To explicitly match case-/accent-insensitively, use <code>&#39;(?i)...&#39;</code>. Example: <code>&#39;(?-i)Mr\\.&#39; &#39;(?-i)Banks&#39;</code></li> <li>Combining criteria using <code>&amp;</code>, <code>|</code> and <code>!</code>. Parentheses can also be used for grouping. Example: <code>[lemma=&#39;bank&#39; &amp; pos=&#39;V&#39;]</code></li> <li>Matchall pattern <code>[]</code> matches any token. Example: <code>&#39;a&#39; [] &#39;day&#39;</code></li> <li>Regular expression operators <code>+</code>, <code>*</code>, <code>?</code>, <code>{n}</code>, <code>{n,m}</code> at the token level. Example: <code>[pos=&#39;ADJ&#39;]+</code></li> <li>Sequences of token constraints. Example: <code>[pos=&#39;ADJ&#39;] &#39;cow&#39;</code></li> <li>Operators <code>|</code>, <code>&amp;</code> and parentheses can be used to build complex sequence queries. Example: <code>&#39;happy&#39; &#39;dog&#39; | &#39;sad&#39; cat&#39;</code></li> <li>Querying with tag positions using e.g. <code>&lt;s&gt;</code> (start of sentence), <code>&lt;/s&gt;</code> (end of sentence), <code>&lt;s/&gt;</code> (whole sentence) or <code>&lt;s&gt; ... &lt;/s&gt;</code> (equivalent to <code>&lt;s/&gt; containing ...</code>). Example: <code>&lt;s&gt; &#39;The&#39; </code>. XML attribute values may be used as well, e.g. <code>&lt;ne type=&#39;PERS&#39;/&gt;</code> (&quot;named entities that are persons&quot;).</li> <li>Using <code>within</code> and <code>containing</code> operators to find hits inside another set of hits. Example: <code>&#39;you&#39; &#39;are&#39; within &lt;s/&gt;</code></li> <li>Using an anchor to capture a token position. Example: <code>&#39;big&#39; A:[]</code>. Captured matches can be used in capture
constraints (see next item) or processed separately later (using the Java interface; capture information is not yet returned by BlackLab Server). Note that BlackLab can actually capture entire groups of tokens as well, similarly to regular expression engines.</li> <li>Capture constraints, such as requiring two captures to contain the same word. Example: <code>&#39;big&#39; A:[] &#39;or&#39; &#39;small&#39; B:[] :: A.word = B.word</code> <ul><li>Integer ranges: <code>[pos=&#39;verb&#39; &amp; pos_confidence=in[50,100]]</code> or <code>&lt;verse number=in[1,10]/&gt;</code> (ranges are always inclusive)</li></ul></li></ul> <p>See below for features not in this list that may be added soon, and let us know if you want a particular feature to be added.</p> <h3 id="differences-from-cwb" tabindex="-1">Differences from CWB <a class="header-anchor" href="#differences-from-cwb" aria-label="Permalink to &quot;Differences from CWB&quot;">​</a></h3> <p>BlackLab&#39;s CQL syntax and behaviour differs in a few ways from CWBs, although they are mostly lesser-used features.</p> <p>For now, here&#39;s what you should know:</p> <ul><li>Case-insensitive search is the default in BlackLab, while CWB and Sketch Engine use case-sensitive search as the default. If you want to match a term case-sensitively, use <code>&#39;(?-i)..&#39;</code> or <code>&#39;(?c)..&#39;</code>.</li> <li>If you want to match a string literally, not as a regular expression, use backslash escaping (<code>&#39;e\\.g\\.&#39;</code>) or a literal string (<code>l&#39;e.g.&#39;</code>)</li> <li>BlackLab supports result set manipulation such as: sorting (including on specific context words), grouping/frequency distribution, subsets, sampling, setting context size, etc. However, these are supported through the REST and Java APIs, not through a command interface like in CWB. See <a href="/server/overview.html">BlackLab Server overview</a>).</li> <li>Querying XML elements and attributes looks natural in BlackLab: <code>&lt;s/&gt;</code> means &quot;sentences&quot;, <code>&lt;s&gt;</code> means &quot;starts of sentences&quot;, <code>&lt;s type=&#39;A&#39;&gt;</code> means &quot;sentence tags with a type attribute with value A&quot;. This natural syntax differs from CWBs in some places, however, particularly when matching XML attributes.</li> <li>In capture constraints (expressions occurring after <code>::</code>), only literal matching (no regex matching) is currently supported.</li> <li>To return whole sentences as the context of hits, pass <code>context=s</code> to BLS.</li> <li>The implication operator <code>-&gt;</code> is currently only supported in capture constraints (expressions after the <code>::</code> operator), not in a regular token constraints.</li> <li>We don&#39;t support the <code>@</code> anchor and corresponding <code>target</code> label; use a named anchor instead.</li> <li>backreferences to anchors only work in capture constraints, so this doesn&#39;t work: <code>A:[] [] [word = A.word]</code>. Instead, use something like: <code>A:[] [] B:[] :: A.word = B.word</code>.</li> <li>Instead of CWBs <code>intersection</code>, <code>union</code> and <code>difference</code> operators, BlackLab supports the <code>&amp;</code>, <code>|</code> and <code>!</code> operators at the top-level of the query, e.g. <code>(&#39;double&#39; [] &amp; [] &#39;trouble&#39;)</code> to match the intersection of these queries, i.e. &#39;double trouble&#39; and <code>(&#39;happy&#39; &#39;dog&#39; | &#39;sad &#39;cat&#39;)</code> to match the union of &#39;happy dog&#39; and &#39;sad cat&#39;. Difference can be achieved by combining <code>!</code> and <code>&amp;</code>, e.g. <code>(&#39;happy&#39; [] &amp; !([] &#39;dog&#39;))</code> to match &#39;happy&#39; followed by anything except &#39;dog&#39; (although this is better expressed as <code>&#39;happy&#39; [word != &#39;dog&#39;]</code>).</li></ul> <h3 id="currently-unsupported-features" tabindex="-1">(Currently) unsupported features <a class="header-anchor" href="#currently-unsupported-features" aria-label="Permalink to &quot;(Currently) unsupported features&quot;">​</a></h3> <p>Some features that are not (yet) supported:</p> <ul><li><code>lbound</code>, <code>rbound</code> functions to get the edge of a region. You can use <code>&lt;s&gt;</code> to get all starts-of-sentences or <code>&lt;/s&gt;</code> to get all ends-of-sentences, however.</li> <li><code>distance</code>, <code>distabs</code> functions and <code>match</code>, <code>matchend</code> anchor points (sometimes used in capture constraints).</li> <li>using an XML element name to mean &#39;token is contained within&#39;, like <code>[(pos = &#39;N&#39;) &amp; !np]</code> meaning &quot;noun NOT inside in an <code>&lt;np/&gt;</code> tag&quot;.</li> <li>a number of less well-known features.</li></ul> <p>If people ask about missing features, we&#39;re happy to work with them to see if it could be added.</p>`,594)]))}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
